 server:=&http.Server{Handler:http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){mu.Lock();defer mu.Unlock();body,_:=io.ReadAll(r.Body);active.Requests=append(active.Requests,Request{r.Method,r.URL.RequestURI(),r.Header.Get("Authorization"),string(body)});status:=active.Status;data:=[]byte("{}");if strings.HasSuffix(r.URL.Path,"/v1/health"){status=active.HealthStatus;data,_=base64.StdEncoding.DecodeString(active.HealthBody)};w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_,_=w.Write(data)})};go func(){_=server.Serve(listener)}();defer server.Close()
